xc_amorium_sectionc.js:
var el = root.querySelector('.typewrite');
if (!el) {
    return;
}

var phrases = [];
try {
    phrases = JSON.parse(el.getAttribute('data-type') || '[]');
} catch (error) {
    phrases = [];
}

phrases = phrases.map(function (line) {
    return String(line).trim();
}).filter(Boolean);

if (!phrases.length) {
    return;
}

var period = parseInt(el.getAttribute('data-period'), 10) || 2000;
var loopNum = 0;
var text = '';
var isDeleting = false;
var wrap = document.createElement('span');
wrap.className = 'wrap';
el.textContent = '';
el.appendChild(wrap);

var tick = function () {
    var fullText = phrases[loopNum % phrases.length];
    text = isDeleting
        ? fullText.substring(0, Math.max(0, text.length - 1))
        : fullText.substring(0, text.length + 1);
    wrap.textContent = text;

    var delay = 200 - Math.random() * 100;
    if (isDeleting) {
        delay /= 2;
    }

    if (!isDeleting && text === fullText) {
        delay = period;
        isDeleting = true;
    } else if (isDeleting && text === '') {
        isDeleting = false;
        loopNum++;
        delay = 500;
    }

    window.setTimeout(tick, delay);
};

tick();

