var trigger = root.querySelector('[data-video]');
if (!trigger) {
    return;
}

var value = trigger.getAttribute('data-video').trim();
var match = value.match(/(?:youtu\.be\/|v=|embed\/|shorts\/)([\w-]{11})/);
var videoId = match ? match[1] : value;
if (!/^[\w-]{11}$/.test(videoId)) {
    trigger.parentElement.remove();
    return;
}

var close = function (modal) {
    modal.remove();
    document.removeEventListener('keydown', modal.onEscape);
};

trigger.addEventListener('click', function (event) {
    event.preventDefault();

    var modal = document.createElement('div');
    modal.className = 'video-modal';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');

    var frame = document.createElement('iframe');
    frame.className = 'video-modal-frame';
    frame.src = 'https://www.youtube-nocookie.com/embed/' + videoId + '?autoplay=1';
    frame.allow = 'autoplay; encrypted-media; picture-in-picture';
    frame.allowFullscreen = true;

    var button = document.createElement('button');
    button.type = 'button';
    button.className = 'video-modal-close';
    button.setAttribute('aria-label', 'Close');
    button.innerHTML = '&times;';

    modal.appendChild(frame);
    modal.appendChild(button);

    modal.onEscape = function (e) {
        if (e.key === 'Escape') {
            close(modal);
        }
    };

    modal.addEventListener('click', function (e) {
        if (e.target !== frame) {
            close(modal);
        }
    });
    document.addEventListener('keydown', modal.onEscape);

    root.appendChild(modal);
    button.focus();
});

