                                <a href="{{ url }}" class="text-lg hover:text-primary dark:text-night-body dark:hover:text-primary transition-all duration-500 font-medium"{% if external %} target="_blank" rel="noopener noreferrer"{% endif %}>{{ feature.title }}</a>
