                            {% endif %}
                            {% if feature.text %}
                                <div class="rich-content text-muted mt-3">{{ feature.text|raw }}</div>
                            {% endif %}
                            {% if url %}
                                <div class="mt-5">
                                    <a href="{{ url }}" class="inline-block tracking-wide align-middle ease-in-out text-center relative after:content-[''] after:absolute after:h-px after:w-0 after:end-0 after:bottom-0 after:start-0 after:transition-all after:duration-500 hover:after:w-full hover:after:end-auto hover:text-primary dark:hover:text-primary after:bg-primary dark:text-night-body"{% if external %} target="_blank" rel="noopener noreferrer"{% endif %}>{{ feature.link_text ?: 'Read More'|_ }} <i class="ri-arrow-right-line"></i></a>
