                    <h6 class="text-primary text-base font-medium uppercase mb-2">{{ data.process_subtitle }}</h6>
                {% endif %}
                {% if data.process_title %}
                    <h3 class="mb-4 md:text-2xl text-xl font-medium">{{ data.process_title }}</h3>
                {% endif %}
                {% if data.process_description %}
                    <div class="rich-content text-muted max-w-xl mx-auto">{{ data.process_description|raw }}</div>
                {% endif %}
            </div>

            <div class="grid grid-cols-1 mt-8">
                <div class="timeline relative">
                    {% for step in steps %}
                        {% set image = step.image ? step.image|media : ('assets/images/process/' ~ stepImages[loop.index0 % 3])|theme %}
