& .timeline::after {
    content: "";
    position: absolute;
    top: 0;
    inset-inline: 0;
    width: 1px;
    height: 100%;
    margin: auto;
    border-inline-start: 2px dashed var(--color-line);
}

& .timeline .date-label-left,
& .timeline .duration-right {
    position: relative;
}

& .timeline .date-label-left::before,
& .timeline .duration-right::before {
    content: "";
    position: absolute;
    top: 0;
    z-index: 10;
    width: 1.75rem;
    height: 1.75rem;
    border: 2px dashed var(--color-line);
    border-radius: 9999px;
    background-color: var(--color-page);
}

& .timeline .date-label-left::after,
& .timeline .duration-right::after {
    content: "";
    position: absolute;
    top: 0.5625rem;
    z-index: 10;
    width: 0.625rem;
    height: 0.625rem;
    border-radius: 9999px;
    background-color: var(--color-primary);
}

& .timeline .date-label-left {
    float: inline-end;
    margin-inline-end: 1.5rem;
}

& .timeline .date-label-left::before {
    inset-inline-end: -2.375rem;
}

& .timeline .date-label-left::after {
    inset-inline-end: -1.8125rem;
}

& .timeline .duration-right {
    float: inline-start;
    margin-inline-start: 1.5rem;
}

& .timeline .duration-right::before {
    inset-inline-start: -2.6875rem;
}

& .timeline .duration-right::after {
    inset-inline-start: -2.125rem;
}

& .timeline .event-description-right {
    margin-inline-start: 1.5rem;
    text-align: start;
}

& .timeline .event-description-left {
    margin-inline-end: 1.5rem;
    text-align: end;
}

@media (max-width: 575px) {
    & .timeline {
        margin-inline-start: 0.75rem;
    }

    & .timeline::after {
        margin: 0;
        margin-inline-start: -0.4375rem;
    }

    & .timeline .event-description-left,
    & .timeline .event-description-right {
        margin: 0 !important;
        margin-inline-start: 1.5rem !important;
        text-align: start;
    }

    & .timeline .duration {
        float: inline-start;
        margin-inline-end: auto !important;
        margin-inline-start: 1.5rem !important;
    }

    & .timeline .duration::before {
        inset-inline-start: -2.75rem;
        inset-inline-end: auto;
    }

    & .timeline .duration::after {
        inset-inline-start: -2.25rem;
        inset-inline-end: auto;
    }
}

.dark & .timeline .date-label-left::before,
.dark & .timeline .duration-right::before {
    border-color: var(--color-night-line);
    background-color: var(--color-night-page);
}

.dark & .timeline::after {
    border-color: var(--color-night-line);
}

