if (!slider) {
    return;
}

var track = slider.querySelector('.testi-track');
var slides = track.children;
var dots = root.querySelector('.testi-dots');
var interval = parseInt(slider.getAttribute('data-interval'), 10) || 3000;
var wide = window.matchMedia('(min-width: 768px)');
var index = 0;
var timer = null;

var perView = function () {
    return wide.matches ? 2 : 1;
};

var pageCount = function () {
    return Math.max(1, slides.length - perView() + 1);
};

var go = function (next) {
    index = (next + pageCount()) % pageCount();
    track.style.transform = 'translateX(' + (-index * 100 / perView()) + '%)';
    Array.prototype.forEach.call(dots.children, function (dot, i) {
        if (i === index) {
            dot.setAttribute('aria-current', 'true');
        }
        else {
            dot.removeAttribute('aria-current');
        }
    });
};

var buildDots = function () {
    dots.innerHTML = '';
    if (pageCount() < 2) {
        return;
    }
    for (var i = 0; i < pageCount(); i++) {
        var dot = document.createElement('button');
        dot.type = 'button';
        dot.setAttribute('aria-label', dots.getAttribute('data-label').replace('#', i + 1));
        dot.addEventListener('click', (function (target) {
