                            </div>

                            <div class="grid grid-cols-1 {{ image ? '' : 'md:grid-cols-2' }} gap-x-6">
                                {% for field in form.fields %}
                                    {% set id = 'form-' ~ section.index ~ '-' ~ field.name %}
                                    {% set requiredMark %}{% if field.required %} <span class="text-danger">*</span>{% endif %}{% endset %}
                                    <div class="relative mb-5 {{ image or field.width == 'half' ? '' : 'md:col-span-2' }}" data-field="{{ field.name }}">
                                        {% if field.type == 'checkbox' and not field.options %}
                                            <label class="inline-flex items-start gap-2 dark:text-night-body cursor-pointer">
                                                <input type="checkbox" name="{{ field.name }}" value="1" class="mt-1 size-4 accent-primary"{% if field.required %} required{% endif %}>
                                                <span>{{ field.label }}{{ requiredMark }}</span>
                                            </label>
                                        {% elseif field.type in ['radio', 'checkbox'] %}
                                            <span class="block dark:text-night-body mb-2">{{ field.label }}{{ requiredMark }}</span>
                                            <div class="flex flex-wrap gap-x-6 gap-y-2">
                                                {% for option in field.options %}
                                                    <label class="inline-flex items-center gap-2 text-muted dark:text-night-muted cursor-pointer">
                                                        <input type="{{ field.type }}" name="{{ field.name }}{{ field.type == 'checkbox' ? '[]' }}" value="{{ option }}" class="size-4 accent-primary"{% if field.required and field.type == 'radio' %} required{% endif %}>
                                                        <span>{{ option }}</span>
                                                    </label>
                                                {% endfor %}
                                            </div>
                                        {% else %}
                                            <label for="{{ id }}" class="dark:text-night-body">{{ field.label }}{{ requiredMark }}</label>
                                            {% if field.type == 'textarea' %}
                                                <textarea name="{{ field.name }}" id="{{ id }}" class="form-input w-full py-2 px-3 border border-line dark:border-night-line focus:ring-0 focus:border-primary/50 dark:bg-night-page dark:text-night-muted rounded outline-none mt-2 h-28 textarea" placeholder="{{ field.placeholder }}"{% if field.required %} required{% endif %}></textarea>
                                            {% elseif field.type == 'select' %}
                                                <select name="{{ field.name }}" id="{{ id }}" class="form-input w-full py-2 px-3 border border-line dark:border-night-line focus:ring-0 focus:border-primary/50 dark:bg-night-page dark:text-night-muted rounded outline-none mt-2 h-10 bg-page"{% if field.required %} required{% endif %}>
                                                    <option value="">{{ field.placeholder ?: '—' }}</option>
                                                    {% for option in field.options %}
                                                        <option value="{{ option }}">{{ option }}</option>
                                                    {% endfor %}
                                                </select>
                                            {% else %}
                                                <input type="{{ field.type }}" name="{{ field.name }}" id="{{ id }}" class="form-input w-full py-2 px-3 border border-line dark:border-night-line focus:ring-0 focus:border-primary/50 dark:bg-night-page dark:text-night-muted rounded outline-none mt-2 h-10" placeholder="{{ field.placeholder }}"{% if field.type == 'number' %} step="any"{% endif %}{% if field.required %} required{% endif %}>
                                            {% endif %}
                                        {% endif %}
                                        <p class="form-error hidden absolute start-0 top-full mt-0.5 text-xs leading-4 text-danger"></p>
                                    </div>
                                {% endfor %}
                            </div>

                            <div class="relative">
                                <button type="submit" class="py-2 px-5 inline-block font-normal tracking-wide border align-middle duration-500 text-base text-center bg-primary hover:bg-primary-dark border-primary hover:border-primary-dark text-white rounded-md disabled:opacity-60">{{ data.button_text ?: 'Send'|_ }}</button>
                                <p class="form-status hidden absolute start-0 end-0 top-full mt-1.5 text-sm leading-5" role="status"></p>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        {% endif %}
    </div>
</section>

