var form = root.querySelector('.amorium-form');
if (!form) {
    return;
}

var button = form.querySelector('[type="submit"]');
var status = form.querySelector('.form-status');

var showStatus = function (message, success) {
    status.textContent = message;
    status.classList.remove('hidden', form.dataset.successClass, form.dataset.errorClass);
    status.classList.add(success ? form.dataset.successClass : form.dataset.errorClass);
};

var clearErrors = function () {
    form.querySelectorAll('.form-error').forEach(function (el) {
        el.textContent = '';
        el.classList.add('hidden');
    });
    status.classList.add('hidden');
};

form.addEventListener('submit', function (event) {
    event.preventDefault();
    clearErrors();
    button.disabled = true;

    fetch(form.action, {
        method: 'POST',
        body: new FormData(form),
        credentials: 'same-origin',
        headers: {
            'Accept': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
        }
    })
        .then(function (response) {
            return response.json().catch(function () {
                return {};
            }).then(function (json) {
                return { ok: response.ok, json: json };
            });
        })
        .then(function (result) {
            if (result.ok) {
                form.reset();
                showStatus(form.dataset.success, true);
                return;
            }

            var errors = result.json.errors || {};
            Object.keys(errors).forEach(function (name) {
                var el = form.querySelector('[data-field="' + name + '"] .form-error');
                if (el) {
                    el.textContent = errors[name];
                    el.classList.remove('hidden');
                }
            });

            showStatus(result.json.message || form.dataset.error, false);
        })
        .catch(function () {
            showStatus(form.dataset.error, false);
        })
        .then(function () {
            button.disabled = false;
        });
});

