{% set before = data.before_image ? data.before_image|media : '' %}
{% set after = data.after_image ? data.after_image|media : '' %}
{% set position = data.start_position matches '/^\\d+$/' ? min(data.start_position, 100) : 50 %}
<section class="relative md:py-24 py-16" id="{{ section.slug }}-{{ section.index }}">
    <div class="container relative">
        {% if data.subtitle or data.title or data.description %}
            <div class="grid grid-cols-1 pb-8 text-center">
                {% if data.subtitle %}
                    <h6 class="text-primary text-base font-medium uppercase mb-2">{{ data.subtitle }}</h6>
                {% endif %}
                {% if data.title %}
                    <h3 class="mb-4 md:text-2xl text-xl font-medium">{{ data.title }}</h3>
                {% endif %}
                {% if data.description %}
                    <div class="rich-content text-muted max-w-xl mx-auto">{{ data.description|raw }}</div>
                {% endif %}
            </div>
        {% endif %}

        {% if before and after %}
            <div class="ba-compare relative max-w-4xl mx-auto overflow-hidden rounded-md shadow-sm shadow-line dark:shadow-night-line select-none" style="--position: {{ position }}%">
                <img src="{{ after }}" alt="{{ data.after_label }}" class="block w-full h-auto" loading="lazy">
                <img src="{{ before }}" alt="{{ data.before_label }}" class="ba-before absolute inset-0 size-full object-cover" loading="lazy">

                {% if data.before_label %}
                    <span class="absolute top-4 left-4 rounded-md bg-contrast/70 px-3 py-1 text-sm text-white pointer-events-none">{{ data.before_label }}</span>
                {% endif %}
                {% if data.after_label %}
                    <span class="absolute top-4 right-4 rounded-md bg-primary px-3 py-1 text-sm text-white pointer-events-none">{{ data.after_label }}</span>
                {% endif %}

                <div class="ba-handle absolute inset-y-0 w-1 bg-white pointer-events-none">
                    <span class="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex size-10 items-center justify-center rounded-full bg-white text-primary shadow-md">
                        <i class="ri-arrow-left-right-line text-xl"></i>
                    </span>
                </div>

                <input type="range" min="0" max="100" value="{{ position }}" class="ba-range absolute inset-0 size-full cursor-ew-resize opacity-0" aria-label="{{ 'Compare before and after'|_ }}">
            </div>
        {% endif %}
    </div>
</section>

