        {% if data.subtitle or data.title or data.description %}
            <div class="grid grid-cols-1 pb-8 text-center">
                {% if data.subtitle %}
                    <h6 class="text-primary text-base font-medium uppercase mb-2">{{ data.subtitle }}</h6>
                {% endif %}
                {% if data.title %}
                    <h1 class="mb-4 md:text-2xl text-xl font-medium">{{ data.title }}</h1>
                {% endif %}
                {% if data.description %}
                    <div class="rich-content text-muted max-w-xl mx-auto">{{ data.description|raw }}</div>
                {% endif %}
