{% if post %}
{% set image = post.featured_image ? post.featured_image|media : '' %}
{% set recent = data.hide_recent ? [] : recentPosts(post, 4) %}
{% set related = data.hide_related ? [] : relatedPosts(post, 3) %}
{% set backUrl = data.back_link ? data.back_link|link : postListUrl() %}
{% if not data.hide_header %}
    <section class="relative table w-full bg-contrast bg-cover bg-center bg-no-repeat md:py-24 py-16" {% if image %}style="background-image: url('{{ image|replace({"'": "%27"}) }}')"{% endif %} id="{{ section.slug }}-{{ section.index }}-header">
        <div class="absolute inset-0 bg-contrast/80"></div>
        <div class="relative container">
            <div class="grid grid-cols-1 text-center">
                <h1 class="text-3xl leading-normal font-medium text-white">{{ post.title }}</h1>
                {% if post.published_at %}
                    <time datetime="{{ post.published_at.toAtomString() }}" class="mt-3 block text-white/50">{{ post.published_at.translatedFormat('j F Y') }}</time>
                {% endif %}
            </div>
        </div>
    </section>
{% endif %}

<section class="relative md:py-24 py-16" id="{{ section.slug }}-{{ section.index }}">
    <div class="container">
        <div class="grid grid-cols-1 gap-7.5 md:grid-cols-12">
            <article class="md:col-span-6 lg:col-span-8">
                <div class="rounded-md p-6 shadow-sm dark:shadow-night-line">
